const A2E = {
  '٠': '0',
  '١': '1',
  '٢': '2',
  '٣': '3',
  '٤': '4',
  '٥': '5',
  '٦': '6',
  '٧': '7',
  '٨': '8',
  '٩': '9'
};
const dig = t => String(t ?? '').replace(/[٠-٩]/g, c => A2E[c]);
const norm = n => dig(n).toLowerCase().replace(/[أإآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه').replace(/[\u064B-\u0652\u0640]/g, '').replace(/\s+(trend|sum)\b/g, '').replace(/[()\[\]]/g, '').replace(/\s+/g, '');
