const fmt = d => d ? new Date(d).toLocaleString('en-GB', {
  day: '2-digit',
  month: 'short',
  year: 'numeric',
  hour: 'numeric',
  minute: '2-digit',
  hour12: true
}) : '—';
const fmtShort = d => d ? new Date(d).toLocaleDateString('en-GB', {
  day: '2-digit',
  month: 'short',
  year: 'numeric'
}) : '—';
const daysSince = d => d ? Math.floor((Date.now() - new Date(d)) / 864e5) : null;
const getP = (o, p) => String(p).split('.').reduce((a, k) => a == null ? a : a[k], o);
const setP = (o, p, v) => {
  const s = String(p).split('.');
  if (s.length === 1) return {
    ...o,
    [s[0]]: v
  };
  return {
    ...o,
    [s[0]]: {
      ...(o[s[0]] || {}),
      [s[1]]: v
    }
  };
};
const igUrl = v => {
  const t = String(v || '').trim();
  if (!t) return '';
  return /^https?:\/\//i.test(t) ? t : 'https://instagram.com/' + t.replace(/^@/, '');
};
const ttUrl = v => {
  const t = String(v || '').trim();
  if (!t) return '';
  return /^https?:\/\//i.test(t) ? t : 'https://tiktok.com/@' + t.replace(/^@/, '');
};
const okUrl = v => /^https?:\/\//i.test(String(v || '').trim());

/* ---------- custom fields ---------- */
function fieldsOf(s, cfg, section) {
  return [...(cfg.customFields || []).filter(f => f.section === section), ...(s && s.localFields || []).filter(f => f.section === section)];
}
function allFields(s, cfg) {
  return [...(cfg.customFields || []), ...(s && s.localFields || [])];
}
function progressOf(s, cfg) {
  let got = 0,
    tot = 0;
  cfg.tasks.filter(t => !t.hidden).forEach(t => {
    const v = t.text ? (s[t.k] || '').trim() ? 'done' : 'none' : s.tasks?.[t.k] || 'none';
    if (v === 'na') return;
    tot++;
    if (v === 'done') got++;else if (v === 'wip') got += .5;
  });
  allFields(s, cfg).filter(f => f.type === 'status' && f.counts).forEach(f => {
    const v = s.custom?.[f.k] || 'none';
    if (v === 'na') return;
    tot++;
    if (v === 'done') got++;else if (v === 'wip') got += .5;
  });
  return tot ? Math.round(got / tot * 100) : 0;
}

/* ---------- normalise records loaded from storage / seed ---------- */
function fixSchool(s, cfg) {
  return {
    custom: {},
    localFields: [],
    tiktok: '',
    joinedAt: null,
    leftAt: null,
    leftOwner1: '',
    leftOwner2: '',
    fromSheet: true,
    ...s,
    tasks: s.tasks || {},
    printables: s.printables || {}
  };
}
function fixProspect(p) {
  return {
    owner: '',
    source: '',
    meetingSet: false,
    meetingAt: '',
    meetingDone: false,
    chance: 'mid',
    notes: '',
    instagram: '',
    tiktok: '',
    drive: '',
    won: false,
    convertedTo: null,
    wonAt: null,
    createdAt: nowISO(),
    ...p
  };
}
const RENAMES = {
  'فاطمة العبيدان': 'فرح العبيدان'
};
const ren = n => RENAMES[n] || n;
function fixDb(d) {
  const cfg = {
    ...CONFIG0,
    ...(d.config || {})
  };
  cfg.customFields = cfg.customFields || [];
  cfg.team = [...new Set((cfg.team || []).map(ren))];
  const fixOwners = s => ({
    ...s,
    owner1: ren(s.owner1),
    owner2: ren(s.owner2),
    leftOwner1: ren(s.leftOwner1),
    leftOwner2: ren(s.leftOwner2)
  });
  return {
    schools: (d.schools || []).map(s => fixOwners(fixSchool(s, cfg))),
    config: cfg,
    users: (d.users || USERS0).map(u => ({
      ...u,
      name: ren(u.name)
    })),
    reqs: d.reqs || [],
    log: d.log || [],
    prospects: (d.prospects || []).map(p => ({
      ...fixProspect(p),
      owner: ren(p.owner)
    }))
  };
}

