function gcalUrl(p) {
  if (!p.meetingAt) return '';
  const st = new Date(p.meetingAt);
  const en = new Date(st.getTime() + 60 * 60 * 1000);
  const z = d => d.toISOString().replace(/[-:]|\.\d{3}/g, '');
  const det = ['مدرسة محتملة: ' + p.name, p.owner ? 'المسؤول: ' + p.owner : '', p.source ? 'عن طريق: ' + p.source : '', 'الاحتمالية: ' + (CHANCE[p.chance] || {}).t, p.notes || ''].filter(Boolean).join('\n');
  return 'https://calendar.google.com/calendar/render?action=TEMPLATE' + '&text=' + encodeURIComponent('ميتنق — ' + p.name) + '&dates=' + z(st) + '/' + z(en) + '&details=' + encodeURIComponent(det);
}
